import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: CreatePostPage(), debugShowCheckedModeBanner: false));
class CreatePostPage extends StatefulWidget { const CreatePostPage({super.key}); @override State<CreatePostPage> createState() => _CreatePostPageState(); }
class _CreatePostPageState extends State<CreatePostPage> { final formKey = GlobalKey<FormState>(); final title = TextEditingController(); final body = TextEditingController(); bool sending = false; String? result; @override void dispose() { title.dispose(); body.dispose(); super.dispose(); }
 Future<void> submit() async { if (!formKey.currentState!.validate()) return; setState(() { sending = true; result = null; }); try { final r = await http.post(Uri.parse('https://jsonplaceholder.typicode.com/posts'), headers: {'Content-Type': 'application/json; charset=UTF-8'}, body: jsonEncode({'title': title.text.trim(), 'body': body.text.trim(), 'userId': 1})); if (r.statusCode != 201) throw Exception('HTTP ${r.statusCode}: ${r.body}'); final data = jsonDecode(r.body) as Map<String, dynamic>; if (mounted) setState(() => result = 'Post created successfully (demo API). Returned ID: ${data['id']}\n${const JsonEncoder.withIndent('  ').convert(data)}'); } catch (e) { if (mounted) setState(() => result = 'Request failed: $e'); } finally { if (mounted) setState(() => sending = false); } }
 @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q14: Send data with http.post')), body: SingleChildScrollView(padding: const EdgeInsets.all(16), child: Form(key: formKey, child: Column(children: [TextFormField(controller: title, decoration: const InputDecoration(labelText: 'Title', border: OutlineInputBorder()), validator: (v) => v == null || v.trim().isEmpty ? 'Enter a title' : null), const SizedBox(height: 12), TextFormField(controller: body, minLines: 4, maxLines: 6, decoration: const InputDecoration(labelText: 'Body', border: OutlineInputBorder()), validator: (v) => v == null || v.trim().isEmpty ? 'Enter a body' : null), const SizedBox(height: 16), FilledButton.icon(onPressed: sending ? null : submit, icon: sending ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.send), label: Text(sending ? 'Sending...' : 'Submit POST request')), if (result != null) Padding(padding: const EdgeInsets.only(top: 16), child: SelectableText(result!))]))));
}
